starter.versions.tf:
terraform {
  required_version = ">= 1.5.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

starter.variables.tf:
variable "lambda_role_arn" {
  description = "Input variable lambda_role_arn."
  type        = string
}

variable "lambda_runtime" {
  description = "Input variable lambda_runtime."
  type        = string
  default     = "python3.12"
}

variable "lambda_memory" {
  description = "Input variable lambda_memory."
  type        = number
  default     = 128
}

variable "api_stage" {
  description = "Input variable api_stage."
  type        = string
  default     = "prod"
}

variable "project_name" {
  description = "Input variable project_name."
  type        = string
  default     = "terraform-practice"
}

variable "environment" {
  description = "Input variable environment."
  type        = string
  default     = "dev"
}

variable "aws_region" {
  description = "Input variable aws_region."
  type        = string
  default     = "us-east-1"
}

starter.main.tf:
provider "aws" {
  region = var.aws_region
}

resource "aws_lambda_function" "this" {
  function_name = "app-fn"
  runtime       = "python3.12"
  handler       = "index.handler"
  filename      = "lambda.zip"
  memory_size   = 128
  environment {
    variables = { TABLE_NAME = "items" }
  }
}

resource "aws_apigatewayv2_api" "this" {
  name          = "app-api"
  protocol_type = "HTTP"
}

resource "aws_apigatewayv2_integration" "this" {
  # TODO - Complete the aws_apigatewayv2_integration resource.
  # Add the arguments and nested blocks required for aws_apigatewayv2_integration.
}

resource "aws_apigatewayv2_route" "this" {
  route_key = "GET /items"
  target    = "integrations/${aws_apigatewayv2_integration.this.id}"
}

resource "aws_apigatewayv2_stage" "this" {
  name        = "$default"
  auto_deploy = true
  access_log_settings {
    destination_arn = aws_cloudwatch_log_group.this.arn
  }
}

resource "aws_lambda_permission" "this" {
  statement_id  = "allow-apigw"
  action        = "lambda:InvokeFunction"
  function_name = aws_lambda_function.this.function_name
  principal     = "apigateway.amazonaws.com"
}

starter.outputs.tf:
output "api_endpoint" {
  value = aws_apigatewayv2_api.this.id
}

output "lambda_arn" {
  value = aws_lambda_function.this.arn
}
